const input = $input.first().json;
const body = input.body || input;
const errors = [];

const senderName = String(body.sender_name || '').trim();
const senderValue = String(body.value_prop || '').trim();
const senderCompany = String(body.sender_company || '').trim();
const calendarLink = String(body.calendar_link || '').trim();
if (!senderName) errors.push('sender_name is required');
if (!senderValue) errors.push('value_prop is required');

const leads = Array.isArray(body.leads) ? body.leads : [];
if (!leads.length) errors.push('leads must be a non-empty array');
if (leads.length > 20) errors.push('maximum 20 leads per request');
leads.forEach((lead, i) => {
  if (!lead || typeof lead !== 'object') { errors.push('leads[' + i + '] must be an object'); return; }
  if (!String(lead.name || '').trim()) errors.push('leads[' + i + '].name is required');
  if (!String(lead.company || '').trim()) errors.push('leads[' + i + '].company is required');
});
if (errors.length) {
  throw new Error('Invalid request: ' + errors.join('; ') + '. Expected: { "sender_name": "...", "value_prop": "...", "leads": [{ "name": "...", "email": "...", "title": "...", "company": "..." }] }');
}

return leads.map(lead => ({
  json: {
    name: String(lead.name).trim(),
    email: String(lead.email || '').trim(),
    title: String(lead.title || '').trim(),
    company: String(lead.company).trim(),
    industry: String(lead.industry || '').trim(),
    companyDescription: String(lead.company_description || '').trim(),
    notes: String(lead.notes || '').trim(),
    senderName,
    senderCompany,
    senderValue,
    calendarLink
  }
}));

