const leads = $('Parse Lead List').all();
const outputs = $input.all();
if (outputs.length !== leads.length) {
  throw new Error('Expected ' + leads.length + ' AI results but received ' + outputs.length);
}

return outputs.map((item, i) => {
  const j = item.json || {};
  const messages = Array.isArray(j.output) ? j.output : [];
  const msg = messages.find(m => m && m.type === 'message') || messages[0];
  const part = msg && Array.isArray(msg.content) ? (msg.content.find(c => c && c.text !== undefined) || msg.content[0]) : null;
  let data = part ? part.text : (j.message && j.message.content !== undefined ? j.message.content : j.text);

  if (typeof data === 'string') {
    const start = data.indexOf('{');
    const end = data.lastIndexOf('}');
    if (start === -1 || end <= start) throw new Error('AI output for lead ' + (i + 1) + ' contained no JSON object');
    try {
      data = JSON.parse(data.slice(start, end + 1));
    } catch (e) {
      throw new Error('Failed to parse AI output for lead ' + (i + 1) + ': ' + e.message);
    }
  }
  if (!data || typeof data !== 'object') throw new Error('Unexpected AI output shape for lead ' + (i + 1));

  const subject = String(data.subject || '').trim();
  const emailBody = String(data.email_body || '').trim();
  if (!subject || !emailBody) throw new Error('AI output for lead ' + (i + 1) + ' is missing subject or email_body');

  return {
    json: {
      ...leads[i].json,
      email_subject: subject,
      email_body: emailBody,
      follow_up: String(data.follow_up || '').trim(),
      generatedAt: new Date().toISOString()
    }
  };
});
